<script setup>
import { onMounted, ref } from 'vue'
import { telegramSettings } from '../services/telegramSettings.js'
const props = defineProps({ session: { type: Object, required: true } })
const form = ref(null), busy = ref(false), error = ref(''), notice = ref('')
const states = { PENDING: 'Очікує надсилання', SENT: 'Надіслано', FAILED: 'Помилка', SKIPPED: 'Надсилання скасовано' }
async function load() { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { form.value = await telegramSettings(props.session.token) } catch (e) { error.value = e.message } finally { busy.value = false } }
async function save() { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { form.value = await telegramSettings(props.session.token, { enabled: form.value.enabled, revision: form.value.revision, recipients: form.value.recipients }); notice.value = 'Налаштування Telegram збережено.' } catch (e) { error.value = e.message } finally { busy.value = false } }
async function retry(id) { if (busy.value) return; if (!window.confirm('Повторити надсилання? Якщо Telegram отримав попереднє повідомлення, але не повернув підтвердження, можлива повторна копія.')) return; busy.value = true; error.value = ''; try { await telegramSettings(props.session.token, null, id); form.value = await telegramSettings(props.session.token) } catch (e) { error.value = e.message } finally { busy.value = false } }
function add() { form.value.recipients.push({ partnerId: '', userId: '' }) }
onMounted(load)
</script>
<template><section><header class="heading"><h2>Telegram</h2><button :disabled="busy" @click="load">Оновити</button></header><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><form v-if="form" @submit.prevent="save"><fieldset :disabled="busy"><label class="toggle"><input v-model="form.enabled" type="checkbox">Надсилати копію в телеграм-бот</label><p>Копії нових замовлень отримують автор замовлення, активні адміністратори з Telegram ID та представники фірми-посередника. Також використовується наявний адміністративний чат сервера.</p><p>Вимкнення зупиняє надсилання черги. Замовлення, створені з вимкненим прапорцем, у чергу не потрапляють. Після ввімкнення раніше підготовлені копії продовжать надсилатися.</p><h3>Представники фірм-посередників</h3><p>Оберіть лише тих користувачів, яким дозволено отримувати копії всіх замовлень філій цієї фірми. Роль бухгалтера сама по собі не підключає сповіщення.</p><div v-for="(recipient, i) in form.recipients" :key="i" class="recipient"><label>Фірма<select v-model.number="recipient.partnerId" required><option disabled value="">Оберіть фірму</option><option v-for="p in form.partners" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label>Отримувач<select v-model.number="recipient.userId" required><option disabled value="">Оберіть користувача</option><option v-for="u in form.users" :key="u.id" :value="u.id" :disabled="!u.linked">{{ u.name }}{{ u.linked ? '' : ' — немає Telegram ID' }}</option></select></label><button type="button" @click="form.recipients.splice(i, 1)">Прибрати</button></div><div class="actions"><button type="button" @click="add">Додати отримувача</button><button class="primary">Зберегти</button></div><p v-if="form.users.some(u => !u.linked)">Без Telegram ID копія користувачу не надсилається. Використовуються наявні прив’язки Telegram зі старої версії.</p></fieldset></form><section v-if="form"><h3>Останні 100 повідомлень</h3><p>Великі замовлення надсилаються кількома частинами. Кожний отримувач має окремий запис доставки.</p><p v-if="!form.deliveries.length">Підготовлених копій ще немає.</p><article v-for="row in form.deliveries" :key="row.id" class="delivery"><strong>Замовлення №{{ row.orderNo }} · частина {{ row.partNo }}</strong><span>{{ row.recipient }}</span><span>{{ states[row.state] || row.state }} · спроб: {{ row.attempts }}</span><small>{{ row.sentAt || row.createdAt }}</small><p v-if="row.error">{{ row.error }}</p><button v-if="row.state === 'FAILED'" :disabled="busy || !form.enabled" @click="retry(row.id)">Повторити надсилання</button></article></section></section></template>
<style scoped>.heading,.actions{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}fieldset{border:0;padding:0;margin:0;min-width:0}.toggle{display:flex;align-items:center;gap:10px;font-weight:600}.toggle input{width:20px;min-height:20px;flex:0 0 20px}.recipient{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto;gap:12px;align-items:end;margin:14px 0}.recipient label{display:grid;gap:6px;min-width:0}select{width:100%;min-width:0}.delivery{display:grid;gap:6px;padding:12px;margin:10px 0;border:1px solid #dce4ec;border-radius:10px;overflow-wrap:anywhere}.delivery button{justify-self:start}@media(max-width:650px){.recipient{grid-template-columns:1fr}}</style>
